        outcome('grupo', 'Parte del grupo quiere quedarse. Os separáis un rato sin que nadie tenga que justificar su presupuesto.', { stats: { responsibility: 2 }, flags: { night_budget: 'elegir un plan que sí puedes pagar' } })
