        outcome('sencillo', 'El capricho es agradable, aunque no transforma la noche. Te sirve saber qué merece tu dinero.', { stats: { mood: 2, knowledge: 1 }, flags: { night_budget: 'revisar qué gastos realmente disfrutas' } })
